"""Generator evaluator for the frontend AST."""
import json
import math
from collections.abc import Iterator
from typing import Any
from jq_parser import (Array, Binary, Binding, Call, Comma, Conditional, Definition,
    Field, Identity, Index, Interpolated, Iterate, Literal, Object, Pipe, Program,
    Reduce, Slice, Try, Unary, Label, Break)

class RuntimeErrorJq(Exception): pass
class BreakSignal(Exception):
    def __init__(self, name: str) -> None: self.name = name
Env = dict[str, Any]

def truth(value: Any) -> bool: return value is not None and value is not False

def evaluate(program: Any, value: Any) -> Iterator[Any]:
    env: Env = {}
    if isinstance(program, Program):
        env["__funcs__"] = {d.name: d for d in program.definitions}
        yield from run(program.body, value, env)
    else: yield from run(program, value, env)

def run(expr: Any, value: Any, env: Env) -> Iterator[Any]:
    if isinstance(expr, Program): yield from run(expr.body, value, env)
    elif isinstance(expr, Identity): yield value
    elif isinstance(expr, Literal):
        if isinstance(expr.value, tuple) and expr.value[0] == "var":
            if expr.value[1] not in env: raise RuntimeErrorJq("undefined variable")
            yield env[expr.value[1]]
        elif isinstance(expr.value, tuple) and expr.value[0] == "call": yield from call(expr.value[1], (), value, env)
        else: yield expr.value
    elif isinstance(expr, Field):
        if not isinstance(value, dict):
            if expr.optional: yield None
            else: raise RuntimeErrorJq("cannot index value")
        else: yield value.get(expr.name)
    elif isinstance(expr, Index):
        # Keep key evaluation lazy.  A jq generator can emit a value before a
        # later key raises; materialising the complete key stream would discard
        # that already-ordered prefix.
        for key in run(expr.key, value, env):
            try: yield index(value, key)
            except RuntimeErrorJq:
                if not expr.optional: raise
                yield None
    elif isinstance(expr, Iterate):
        if isinstance(value, list): yield from value
        elif isinstance(value, dict): yield from value.values()
        elif expr.optional: return
        elif value is not None: raise RuntimeErrorJq("cannot iterate value")
    elif isinstance(expr, Slice):
        for start in [None] if expr.start is None else run(expr.start, value, env):
            for end in [None] if expr.end is None else run(expr.end, value, env):
                if not isinstance(value, (list, str)): raise RuntimeErrorJq("cannot slice value")
                yield value[int(start) if start is not None else None:int(end) if end is not None else None]
    elif isinstance(expr, Interpolated):
        streams = [list(run(part, value, env)) for part in expr.parts]
        for pieces in __import__("itertools").product(*streams):
            yield "".join(piece if isinstance(piece, str) else json.dumps(piece, separators=(",", ":"), ensure_ascii=False) for piece in pieces)
    elif isinstance(expr, Pipe):
        for item in run(expr.left, value, env): yield from run(expr.right, item, env)
    elif isinstance(expr, Comma): yield from run(expr.left, value, env); yield from run(expr.right, value, env)
    elif isinstance(expr, Array): yield list(run(expr.expression, value, env))
    elif isinstance(expr, Object):
        partials = [({}, value)]
        for key_expr, val_expr in expr.pairs:
            next_partials = []
            for obj, original in partials:
                keys = list(run(key_expr, original, env))
                vals = list(run(val_expr, original, env))
                for key in keys:
                    for val in vals:
                        new = dict(obj); new[str(key)] = val; next_partials.append((new, original))
            partials = next_partials
        yield from (obj for obj, _ in partials)
    elif isinstance(expr, Unary):
        for item in run(expr.expression, value, env): yield -item if expr.operator == "-" else item
    elif isinstance(expr, Binary): yield from binary(expr.operator, expr.left, expr.right, value, env)
    elif isinstance(expr, Conditional):
        for condition in run(expr.condition, value, env): yield from run(expr.yes if truth(condition) else expr.no, value, env)
    elif isinstance(expr, Try):
        try: yield from run(expr.expression, value, env)
        except RuntimeErrorJq as error:
            if expr.handler is not None: yield from run(expr.handler, str(error), env)
    elif isinstance(expr, Label):
        try:
            yield from run(expr.body, value, env)
        except BreakSignal as signal:
            if signal.name != expr.name: raise
    elif isinstance(expr, Break):
        raise BreakSignal(expr.name)
    elif isinstance(expr, Binding):
        for bound in run(expr.expression, value, env):
            child = dict(env); child[expr.name] = bound; yield from run(expr.body, value, child)
    elif isinstance(expr, Reduce):
        accumulators = list(run(expr.initial, value, env))
        for item in run(expr.source, value, env):
            new = []
            for accumulator in accumulators:
                child=dict(env); child[expr.name]=item; new.extend(run(expr.update, accumulator, child))
            accumulators=new
        yield from accumulators
    elif isinstance(expr, Call): yield from call(expr.name, expr.args, value, env)
    else: raise RuntimeErrorJq("unknown expression")

def index(value: Any, key: Any) -> Any:
    if isinstance(value, dict): return value.get(str(key))
    if isinstance(value, list) and isinstance(key, (int, float)):
        i=int(key); return value[i] if -len(value) <= i < len(value) else None
    if isinstance(value, str) and isinstance(key, (int, float)): return value[int(key)]
    raise RuntimeErrorJq("cannot index value")

def binary(op: str, left: Any, right: Any, value: Any, env: Env) -> Iterator[Any]:
    if op == "//":
        values=list(run(left,value,env)); good=[x for x in values if truth(x)]
        yield from (good if good else run(right,value,env)); return
    for a in run(left,value,env):
        for b in run(right,value,env):
            if op == "+": result = b if a is None else a if b is None else a+b
            elif op == "-": result = a-b
            elif op == "*": result = a*b
            elif op == "/":
                if b == 0: raise RuntimeErrorJq("division by zero")
                result = a/b
            elif op == "%": result = a%b
            elif op in {"==","!=","<",">","<=",">="}: result = {"==":a==b,"!=":a!=b,"<":a<b,">":a>b,"<=":a<=b,">=":a>=b}[op]
            elif op == "and": result = truth(a) and truth(b)
            elif op == "or": result = truth(a) or truth(b)
            else: raise RuntimeErrorJq(f"unsupported operator {op}")
            yield result

def call(name: str, args: tuple[Any, ...], value: Any, env: Env) -> Iterator[Any]:
    if name == "empty": return
    if name == "length": yield len(value) if isinstance(value,(str,list,dict)) else abs(value) if isinstance(value,(int,float)) else 0; return
    if name == "type": yield "null" if value is None else "boolean" if isinstance(value,bool) else "number" if isinstance(value,(int,float)) else "string" if isinstance(value,str) else "array" if isinstance(value,list) else "object"; return
    if name == "tostring": yield value if isinstance(value,str) else json.dumps(value,separators=(",",":"),ensure_ascii=False); return
    if name == "map":
        yield [item for source in run(Iterate(Identity()),value,env) for item in run(args[0],source,env)]; return
    if name == "select":
        if any(truth(x) for x in run(args[0],value,env)): yield value
        return
    if name == "add":
        vals=value; result=None
        for item in vals: result=item if result is None else result+item
        yield result; return
    funcs=env.get("__funcs__",{})
    definition: Definition | None = funcs.get(name)
    if definition is not None:
        child=dict(env)
        for param, argument in zip(definition.args,args): child[param] = argument
        yield from run(definition.body,value,child); return
    raise RuntimeErrorJq(f"unknown function {name}")

"""Precedence-aware jq parser and immutable AST."""
from dataclasses import dataclass
import json
from typing import Any
from jq_lexer import Token, tokenize

class ParseError(ValueError):
    pass

@dataclass(frozen=True)
class Identity: pass
@dataclass(frozen=True)
class Literal: value: Any
@dataclass(frozen=True)
class Field: base: Any; name: str; optional: bool = False
@dataclass(frozen=True)
class Index: base: Any; key: Any; optional: bool = False
@dataclass(frozen=True)
class Iterate: base: Any; optional: bool = False
@dataclass(frozen=True)
class Slice: base: Any; start: Any; end: Any; optional: bool = False
@dataclass(frozen=True)
class Pipe: left: Any; right: Any
@dataclass(frozen=True)
class Comma: left: Any; right: Any
@dataclass(frozen=True)
class Binary: operator: str; left: Any; right: Any
@dataclass(frozen=True)
class Unary: operator: str; expression: Any
@dataclass(frozen=True)
class Array: expression: Any
@dataclass(frozen=True)
class Object: pairs: tuple[tuple[Any, Any], ...]
@dataclass(frozen=True)
class Interpolated: parts: tuple[Any, ...]
@dataclass(frozen=True)
class Call: name: str; args: tuple[Any, ...]
@dataclass(frozen=True)
class Binding: expression: Any; name: str; body: Any
@dataclass(frozen=True)
class Conditional: condition: Any; yes: Any; no: Any
@dataclass(frozen=True)
class Try: expression: Any; handler: Any | None
@dataclass(frozen=True)
class Reduce: source: Any; name: str; initial: Any; update: Any
@dataclass(frozen=True)
class Label: name: str; body: Any
@dataclass(frozen=True)
class Break: name: str
@dataclass(frozen=True)
class Definition: name: str; args: tuple[str, ...]; body: Any
@dataclass(frozen=True)
class Program: definitions: tuple[Definition, ...]; body: Any; module: Any | None = None


def _is_constant(node: Any) -> bool:
    """Return whether a node is a compile-time JSON value."""
    if isinstance(node, Literal):
        return not (isinstance(node.value, tuple) and node.value[0] in {"var", "call"})
    if isinstance(node, Array):
        return _is_constant(node.expression)
    if isinstance(node, Object):
        return all(_is_constant(key) and _is_constant(value) for key, value in node.pairs)
    return False


def _validate_variables(program: Program) -> None:
    """Reject variable references that are not visible at compile time."""
    def visit(node: Any, bound: frozenset[str], labels: frozenset[str] = frozenset()) -> None:
        if isinstance(node, Literal):
            if isinstance(node.value, tuple) and node.value[0] == "var" and node.value[1] not in bound:
                raise ParseError(f"undefined variable: ${node.value[1]}")
            return
        if isinstance(node, Binding):
            visit(node.expression, bound, labels)
            visit(node.body, bound | {node.name}, labels)
            return
        if isinstance(node, Break):
            if node.name not in labels:
                raise ParseError(f"undefined break label: ${node.name}")
            return
        if isinstance(node, Label):
            visit(node.body, bound, labels | {node.name})
            return
        if isinstance(node, Reduce):
            visit(node.source, bound, labels)
            visit(node.initial, bound, labels)
            visit(node.update, bound | {node.name}, labels)
            return
        if isinstance(node, Definition):
            visit(node.body, bound | frozenset(node.args))
            return
        if isinstance(node, Program):
            for definition in node.definitions:
                visit(definition, frozenset())
            visit(node.body, frozenset())
            if node.module is not None:
                if not _is_constant(node.module):
                    raise ParseError("module metadata must be constant")
                if not isinstance(node.module, Object):
                    raise ParseError("module metadata must be an object")
            return
        if isinstance(node, Object):
            for key, value in node.pairs:
                if isinstance(key, Literal) and not isinstance(key.value, str):
                    raise ParseError("constant object key must be a string")
                visit(key, bound)
                visit(value, bound)
            return
        if isinstance(node, (Identity,)):
            return
        if hasattr(node, "__dataclass_fields__"):
            for field in node.__dataclass_fields__:
                child = getattr(node, field)
                if isinstance(child, tuple):
                    for item in child:
                        if hasattr(item, "__dataclass_fields__"):
                            visit(item, bound, labels)
                        elif isinstance(item, tuple):
                            for nested in item:
                                if hasattr(nested, "__dataclass_fields__"):
                                    visit(nested, bound, labels)
                elif hasattr(child, "__dataclass_fields__"):
                    visit(child, bound, labels)

    visit(program, frozenset())

PRECEDENCE = {"//": 2, "=": 3, "|=": 3, "+=": 3, "-=": 3, "*=": 3,
              "/=": 3, "%=": 3, "or": 4, "and": 5, "==": 6, "!=": 6,
              "<": 6, ">": 6, "<=": 6, ">=": 6, "+": 7, "-": 7,
              "*": 8, "/": 8, "%": 8, "|": 1, ",": 0}

class Parser:
    def __init__(self, tokens: list[Token]): self.tokens, self.pos = tokens, 0
    def current(self) -> Token: return self.tokens[self.pos]
    def accept(self, kind: str) -> Token | None:
        if self.current().kind == kind:
            token = self.current(); self.pos += 1; return token
        return None
    def take(self, kind: str) -> Token:
        token = self.accept(kind)
        if token is None: raise ParseError(f"expected {kind}, got {self.current().kind}")
        return token
    def parse(self) -> Program:
        defs: list[Definition] = []
        while self.accept("def"):
            name = self.take("IDENT").text
            args: list[str] = []
            if self.accept("("):
                if self.current().kind != ")":
                    while True:
                        token = self.current()
                        if token.kind not in {"IDENT", "BINDING"}: raise ParseError("invalid function parameter")
                        args.append(token.text); self.pos += 1
                        if not self.accept(";"): break
                self.take(")")
            self.take(":"); body = self.expression(0); self.take(";")
            defs.append(Definition(name, tuple(args), body))
        module = None
        if self.accept("module"):
            module = self.expression(0)
            self.take(";")
        body = self.expression(0)
        self.take("EOF")
        program = Program(tuple(defs), body, module)
        _validate_variables(program)
        return program
    def expression(self, minimum: int) -> Any:
        left = self.prefix()
        if minimum <= 1 and self.accept("as"):
            name = self.take("BINDING").text
            self.take("|")
            left = Binding(left, name, self.expression(1))
        while self.current().kind in PRECEDENCE and PRECEDENCE[self.current().kind] >= minimum:
            op = self.current().kind; precedence = PRECEDENCE[op]; self.pos += 1
            right = self.expression(precedence + (0 if op in {"|", "//", "="} else 1))
            left = Pipe(left, right) if op == "|" else Comma(left, right) if op == "," else Binary(op, left, right)
        return left
    def prefix(self) -> Any:
        token = self.current()
        if token.kind in {"-", "+"}:
            self.pos += 1; return Unary(token.kind, self.expression(9))
        if token.kind == "try":
            self.pos += 1; expr = self.expression(3)
            handler = None
            if self.accept("catch"): handler = self.expression(3)
            return Try(expr, handler)
        if token.kind == "label":
            self.pos += 1
            name = self.take("BINDING").text
            self.take("|")
            return Label(name, self.expression(1))
        if token.kind == "break":
            self.pos += 1
            return Break(self.take("BINDING").text)
        if token.kind == "if":
            self.pos += 1; condition = self.expression(0); self.take("then"); yes = self.expression(0)
            if self.accept("else"): no = self.expression(0)
            else: no = Identity()
            self.take("end"); return Conditional(condition, yes, no)
        if token.kind == "reduce":
            self.pos += 1; source = self.expression(3); self.take("as"); name = self.take("BINDING").text
            self.take("("); initial = self.expression(0); self.take(";"); update = self.expression(0); self.take(")")
            return Reduce(source, name, initial, update)
        if token.kind == "(":
            self.pos += 1; value = self.expression(0); self.take(")")
        elif token.kind == ".": self.pos += 1; value = Identity()
        elif token.kind == "FIELD": self.pos += 1; value = Field(Identity(), token.text)
        elif token.kind == "BINDING": self.pos += 1; value = Literal(("var", token.text))
        elif token.kind == "LITERAL": self.pos += 1; value = Literal(json.loads(token.text))
        elif token.kind == "STRING": self.pos += 1; value = self.string_value(token.text)
        elif token.kind == "FORMAT": self.pos += 1; value = Call(token.text, ())
        elif token.kind == "IDENT":
            self.pos += 1; name = token.text
            if self.accept("("):
                args = []
                if self.current().kind != ")":
                    while True:
                        args.append(self.expression(0))
                        if not self.accept(";"): break
                self.take(")"); value = Call(name, tuple(args))
            else: value = Literal(True if name == "true" else False if name == "false" else None if name == "null" else ("call", name))
        elif token.kind == "[":
            self.pos += 1
            if self.accept("]"):
                value = Array(Identity())
            else:
                inner = self.expression(0); self.take("]"); value = Array(inner)
        elif token.kind == "{": value = self.object_value()
        else: raise ParseError(f"unexpected token {token.kind}")
        while True:
            if self.accept("."):
                if self.accept("["):
                    key = self.expression(0); self.take("]"); value = Index(value, key)
                else: value = Field(value, self.take("STRING").text[1:-1])
            elif self.current().kind == "FIELD": value = Field(value, self.take("FIELD").text)
            elif self.accept("["):
                if self.accept("]"): value = Iterate(value)
                else:
                    first = None if self.current().kind == ":" else self.expression(0)
                    if self.accept(":"):
                        end = None if self.current().kind == "]" else self.expression(0); self.take("]"); value = Slice(value, first, end)
                    else: self.take("]"); value = Index(value, first)
            elif self.accept("?"):
                if isinstance(value, Field): value = Field(value.base, value.name, True)
                elif isinstance(value, Iterate): value = Iterate(value.base, True)
                elif isinstance(value, Index): value = Index(value.base, value.key, True)
                else: value = Try(value, None)
            else: break
        return value
    def object_value(self) -> Object:
        self.take("{"); pairs: list[tuple[Any, Any]] = []
        if self.accept("}"): return Object(tuple(pairs))
        while True:
            key = self.current()
            if key.kind in {"IDENT", "as", "def", "if", "then", "else", "end", "and", "or"}:
                self.pos += 1; key_ast: Any = Literal(key.text)
                if self.accept(":"): val = self.expression(1)
                else: val = Field(Identity(), key.text)
            elif key.kind == "STRING": self.pos += 1; key_ast = self.string_value(key.text); self.take(":"); val = self.expression(1)
            elif key.kind == "BINDING": self.pos += 1; key_ast = Literal(key.text); val = Literal(("var", key.text)) if not self.accept(":") else self.expression(1)
            elif key.kind == "(":
                self.pos += 1
                key_ast = self.expression(0)
                self.take(")"); self.take(":"); val = self.expression(1)
            else: raise ParseError("invalid object key")
            pairs.append((key_ast, val))
            if not self.accept(","): break
        self.take("}"); return Object(tuple(pairs))
    def string_value(self, text: str) -> Any:
        body = text[1:-1]; parts: list[Any] = []; literal = []; index = 0
        while index < len(body):
            if body.startswith("\\(", index):
                if literal: parts.append(Literal(json.loads('"'+''.join(literal)+'"'))); literal=[]
                depth=1; cursor=index+2
                while cursor < len(body) and depth:
                    if body[cursor] == "(": depth += 1
                    elif body[cursor] == ")": depth -= 1
                    cursor += 1
                if depth: raise ParseError("unterminated interpolation")
                parts.append(parse(body[index+2:cursor-1])); index=cursor
            else: literal.append(body[index]); index += 1
        if literal or not parts: parts.append(Literal(json.loads('"'+''.join(literal)+'"')))
        return parts[0] if len(parts)==1 else Interpolated(tuple(parts))

def parse(source: str) -> Program: return Parser(tokenize(source)).parse()

"""Lexer for the jq frontend.

The lexer deliberately keeps string tokens intact; interpolation is parsed by
the parser because its contents are jq expressions rather than JSON text.
"""
from dataclasses import dataclass
import json
import re


@dataclass(frozen=True)
class Token:
    kind: str
    text: str


class LexError(ValueError):
    pass


KEYWORDS = {
    "as", "import", "include", "module", "def", "if", "then", "else",
    "elif", "and", "or", "end", "reduce", "foreach", "try", "catch",
    "label", "break",
}
OPERATORS = (
    "//=", "?//", "|=", "+=", "-=", "*=", "/=", "%=", "==", "!=",
    "<=", ">=", "..",
)
SINGLE = set(".?=,;:|+-*/%()[]{}$<>")
NUMBER = re.compile(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?\Z")
WORD = re.compile(r"(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*\Z")


def _string_end(source: str, start: int) -> int:
    index = start + 1
    while index < len(source):
        if source[index] == '"':
            backslashes = 0
            cursor = index - 1
            while cursor >= start and source[cursor] == "\\":
                backslashes += 1
                cursor -= 1
            if backslashes % 2 == 0:
                raw = source[start:index + 1]
                try:
                    # Validate ordinary JSON escapes now.  \( is jq
                    # interpolation and is intentionally validated later.
                    json.loads(raw.replace("\\(", "\\\\(")) if "\\(" in raw else json.loads(raw)
                except json.JSONDecodeError as error:
                    raise LexError("invalid string escape") from error
                return index + 1
        if source[index] == "\n" or source[index] == "\r":
            raise LexError("unterminated string")
        index += 1
    raise LexError("unterminated string")


def tokenize(source: str) -> list[Token]:
    result: list[Token] = []
    index = 0
    while index < len(source):
        char = source[index]
        if char.isspace():
            index += 1
            continue
        if char == "#":
            index += 1
            while index < len(source):
                if source[index] in "\r\n":
                    index += 1
                    break
                # An odd trailing backslash continues the comment line.
                if source[index] == "\\" and index + 1 < len(source) and source[index + 1] == "\n":
                    index += 2
                    continue
                index += 1
            continue
        if char == '"':
            end = _string_end(source, index)
            result.append(Token("STRING", source[index:end]))
            index = end
            continue
        if char == "@":
            match = re.match(r"@[A-Za-z0-9_]+", source[index:])
            if not match:
                raise LexError("invalid format token")
            text = match.group(0)
            result.append(Token("FORMAT", text[1:]))
            index += len(text)
            continue
        operator = next((value for value in OPERATORS if source.startswith(value, index)), None)
        if operator is not None:
            result.append(Token(operator, operator))
            index += len(operator)
            continue
        if char == "." and index + 1 < len(source) and re.match(r"[A-Za-z_]", source[index + 1]):
            match = re.match(r"\.[A-Za-z_][A-Za-z_0-9]*", source[index:])
            assert match is not None
            text = match.group(0)
            result.append(Token("FIELD", text[1:]))
            index += len(text)
            continue
        if char == "$":
            match = re.match(r"\$(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*", source[index:])
            if not match:
                result.append(Token("$", "$"))
                index += 1
            else:
                text = match.group(0)
                result.append(Token("BINDING", text[1:]))
                index += len(text)
            continue
        if char in SINGLE:
            result.append(Token(char, char))
            index += 1
            continue
        end = index
        while end < len(source) and not source[end].isspace() and source[end] not in SINGLE and source[end] != '"' and source[end] != "#":
            if any(source.startswith(op, end) for op in OPERATORS):
                break
            end += 1
        text = source[index:end]
        if not text:
            raise LexError(f"invalid character: {source[index]!r}")
        if text in {"true", "false", "null"} or NUMBER.fullmatch(text):
            kind = "LITERAL"
        elif WORD.fullmatch(text):
            kind = text if text in KEYWORDS else "IDENT"
        else:
            raise LexError(f"invalid token: {text}")
        result.append(Token(kind, text))
